import{_ as a,o as e,c as r,a0 as d}from"./chunks/framework.DzvPB4Y-.js";const m=JSON.parse('{"title":"一维分切 CSP1D","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/csp1d/index.md","filePath":"zh-cn/frameworks/csp1d/index.md"}'),o={name:"zh-cn/frameworks/csp1d/index.md"};function l(i,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="一维分切-csp1d" tabindex="-1">一维分切 CSP1D <a class="header-anchor" href="#一维分切-csp1d" aria-label="Permalink to &quot;一维分切 CSP1D&quot;">​</a></h1><p>原料具有可用幅宽，订单需要不同宽度的产品。选择切割方案及其使用次数，让产出满足需求，并按配置处理原料、设备、超欠产与余料。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>产品与需求</td><td><code>Product</code> / <code>ProductDemand</code></td><td>宽度、可选长度、数量和计量模式</td></tr><tr><td>原料与设备</td><td><code>Material</code> / <code>Machine</code></td><td>幅宽、批次、设备及可选资源限制</td></tr><tr><td>切割方案</td><td><code>CuttingPlan</code></td><td>每次执行对各产品的产出贡献</td></tr><tr><td>问题</td><td><code>Csp1dProblem</code></td><td>领域数据与求解配置</td></tr><tr><td>求解与结果</td><td><code>Csp1dMilp</code> / <code>Csp1dColumnGeneration</code></td><td>方案使用、产出、需求满足与增强指标</td></tr></tbody></table><p><strong>变量是方案使用次数，不是产品产量。</strong> 产品产量由各方案贡献乘使用次数汇总。卷数、片数、长度和重量需求不能互换。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>两种语言都提供普通 MILP 和列生成入口，但 adapter、返回类型与配置不同。先学普通入口，再观察初始方案、LP、定价、加列和最终整数求解。</p><p>下游 HTTP DTO、租户、公式语言和运行时策略留在业务适配层，不属于这个通用内核。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>需求的产品、数量和单位必须同时明确；不能把不同单位的需求合成一个裸数。</li><li>设备有数据不代表每一种产能约束都自动存在，必须核对方案资源消耗与配置。</li><li>初始方案不足可能需要可行性阶段；受限池不可行不等于完整业务问题不可行。</li><li>启发式或有界定价结束不自动证明整数最优。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-slitting.html">第一次卷材分切</a>，检查方案如何贡献产量。</li><li>增加超产上界、欠产惩罚、余料和长度配置，再考虑自定义管线。</li><li>阅读<a href="/ospf/zh-cn/examples/framework-example3.html">复杂示例 3</a>及其上下文模型，理解组合与列生成。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-csp1d/README_ch.md" target="_blank" rel="noreferrer">Kotlin API 与扩展契约</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-csp1d/README_ch.md" target="_blank" rel="noreferrer">Rust API 与求解生命周期</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">需求口径与业务规则</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',17)])])}const f=a(o,[["render",l]]);export{m as __pageData,f as default};
